var n=`0297-shopska-salad`;var t=`world-0297`;var s=`MK`;var a=`southern-europe`;var o=4;var r=12;var l={en:`Shopska Salad`,ua:`Шопський салат`};var d={en:`A traditional North Macedonia dish made with tomato, cucumber, green bell pepper, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Північна Македонія. Основні інгредієнти: помідор, огірок, зелений солодкий перець, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:7,i:[[`tomato`,440,`g`],[`cucumber`,300,`g`],[`green-bell-pepper`,180,`g`],[`yellow-onion`,100,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:3,i:[[`extra-virgin-olive-oil`,55,`ml`],[`white-wine-vinegar`,20,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`feta`,200,`g`]]}];var h={slug:n,id:t,country:`MK`,region:a,servings:4,minutes:12,title:l,text:d,steps:g};export{s as country,h as default,t as id,r as minutes,a as region,o as servings,n as slug,g as steps,d as text,l as title};